def analyze(text):
    """Use this again in any later cell: analyze('your argument here')."""
    result = classifier.predict_full(text).display_result()
    display(pd.DataFrame([{"Fallacy": result["fallacy"], "Confidence display": result["confidence_percent"], "Explanation": result["explanation"]}]))
    if result["secondary_fallacies"]:
        display(pd.DataFrame(result["secondary_fallacies"]))
    return result
