def download_submission():
    """Run download_submission() in another cell to save source and fresh results."""
    import zipfile
    target = PROJECT.parent / (PROJECT.name + "_submission.zip")
    with zipfile.ZipFile(target, "w", zipfile.ZIP_DEFLATED) as archive:
        for path in PROJECT.rglob("*"):
            if path.is_file() and "__pycache__" not in path.parts and ".pytest_cache" not in path.parts and path.suffix != ".db":
                archive.write(path, path.relative_to(PROJECT))
    from google.colab import files
    files.download(str(target))
    return str(target)
